def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp) if isinstance(resp, dict) else resp
    outcome = result.get("outcome") if isinstance(result, dict) else None
    limit = result.get("credit_limit", 0) if isinstance(result, dict) else 0

    # Network referral rule (all partners): self_employed applicant whose
    # requested_limit is strictly above 6000 must go to manual review
    # instead of being issued. A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000
            and outcome == "approved"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": int(limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    if outcome == "manual_review":
        # Manual review is NOT a decline: per spec section 3, place it in
        # the manual review queue. Do not convert it to a decline.
        return {"action": "queue_review", "limit": 0}

    # Unknown outcome: be safe, send to manual review rather than decline.
    return {"action": "queue_review", "limit": 0}
